SQLite

स्थानीय या स्मृति-स्थित SQLite डेटाबेस खोलें और उपलब्ध runtime संस्करण पढ़ें।

ब्राउज़र लक्ष्य · host

असमकालिक संसाधन(ड:असमडेटासंबंध=प्रतीक्षा असमडेटा.एसक्यूलाइट(":memory:")){
    असमकालिक संसाधन(क:असमडेटाकथन=प्रतीक्षा ड.तैयार("CREATE TABLE notes(id INTEGER PRIMARY KEY,title TEXT NOT NULL)")){
        स्थिर बदले:पूर्णांक=प्रतीक्षा क.चलाओ();
    }
    प्रतीक्षा सहेजो(ड);
    असमकालिक संसाधन(क:असमडेटाकथन=प्रतीक्षा ड.तैयार("SELECT title FROM notes ORDER BY id")){
        जबतक(प्रतीक्षा क.अगला()){लिखो(क.पाठलो(०));}
    }
}


संसाधन (ड: डेटासंबंध = डेटा.एसक्यूलाइट("tasks.db")) {
    लिखो("लागू बदलाव: ",योजना.लागूकरो(ड));
    योजना.जाँचो(ड);
    प्रत्येक (योजना.स्थिति(ड) में म: माइग्रेशनस्थिति) { लिखो(म.संस्करण," ",म.नाम," ",म.लागू); }
    संसाधन (क: डेटाकथन = ड.तैयार("INSERT INTO tasks(id,title) VALUES (?,?) ON CONFLICT(id) DO NOTHING")) {
        क.पूर्णांकरखो(१,१); क.पाठरखो(२,"भारत😀 का स्वागत"); क.चलाओ();
    }
    संसाधन (क: डेटाकथन = ड.तैयार("SELECT title FROM tasks ORDER BY id")) { जबतक (क.अगला()) { लिखो(क.पाठलो(०)); } }
}

